    private function renderNginx(array $site,string $runtime,string $root,array $runtimeInfo,int $port,string $cert,string $key): string { $base="server {\n    listen {$port} ssl;\n    server_name _;\n    ssl_certificate {$cert};\n    ssl_certificate_key {$key};\n    client_max_body_size 64m;\n    add_header X-Content-Type-Options nosniff always;\n";if($runtime==='NODE')return $base."    location / { proxy_pass {$runtimeInfo['upstream']}; proxy_http_version 1.1; proxy_set_header Host \\$host; proxy_set_header X-Forwarded-Proto https; proxy_set_header X-Forwarded-For \\$proxy_add_x_forwarded_for; }\n}\n";$base.="    root {$root};\n    index index.php index.html index.htm;\n";if($runtime==='PHP')$base.="    location / { try_files \\$uri \\$uri/ /index.php?\\$query_string; }\n    location ~ \\.php$ { try_files \\$uri =404; include fastcgi_params; fastcgi_param SCRIPT_FILENAME \\$document_root\\$fastcgi_script_name; fastcgi_pass unix:{$runtimeInfo['socket']}; }\n    location ~ /\\. { deny all; }\n";else $base.="    location / { try_files \\$uri \\$uri/ =404; }\n";return $base."}\n"; }
    private function serverIdentity(): array
    {
        $output=$this->run(['/usr/sbin/nginx','-T'])['out'];
        $host=getenv('AWH_PUBLIC_HOST');
        if(!is_string($host)||!self::validHost($host)){
            preg_match_all('/server_name\s+([^;]+);/',$output,$matches);$host=null;
            foreach($matches[1]??[] as $chunk)foreach(preg_split('/\s+/',trim($chunk))?:[] as $candidate){
                if(self::validHost($candidate)&&$candidate!=='_'&&$candidate!=='localhost'&&!str_starts_with($candidate,'*.')){$host=$candidate;break 2;}
            }
        }
        if(!is_string($host))throw new HubManagedHostingOperatorException('Public VPS address is unavailable','HOSTING_PUBLIC_HOST_UNAVAILABLE');
        $cert=null;$key=null;
        if(filter_var($host,FILTER_VALIDATE_IP)!==false){
            $ipCert='/etc/letsencrypt/live/'.$host.'/fullchain.pem';$ipKey='/etc/letsencrypt/live/'.$host.'/privkey.pem';
            if(is_file($ipCert)&&!is_link($ipCert)&&is_file($ipKey)&&!is_link($ipKey)){$cert=$ipCert;$key=$ipKey;}
        }
        if($cert===null||$key===null){
            if(!preg_match('/ssl_certificate\s+([^;\s]+);/',$output,$c)||!preg_match('/ssl_certificate_key\s+([^;\s]+);/',$output,$k))throw new HubManagedHostingOperatorException('Existing HTTPS identity is unavailable','HOSTING_TLS_UNAVAILABLE');
            $cert=$c[1];$key=$k[1];
        }
        if(!str_starts_with($cert,'/')||!str_starts_with($key,'/'))throw new HubManagedHostingOperatorException('HTTPS identity is unsafe','HOSTING_TLS_UNAVAILABLE');
        $check=filter_var($host,FILTER_VALIDATE_IP)!==false?['/usr/bin/openssl','x509','-in',$cert,'-noout','-checkip',$host]:['/usr/bin/openssl','x509','-in',$cert,'-noout','-checkhost',$host];
        $verified=$this->runOptional($check);
        if($verified['code']!==0||!str_contains($verified['out'],'does match certificate'))throw new HubManagedHostingOperatorException('HTTPS certificate does not cover the public VPS address','HOSTING_TLS_UNAVAILABLE');
        return [$host,$cert,$key];
    }
