    private function nodeUnit(string $site): string { return 'awh-site-'.substr(str_replace('-','',$site),0,12).'.service'; }
    private function site(string $id): array { if(!self::validUuid($id))throw new HubManagedHostingOperatorException('Site identity is invalid','HOSTING_CHECKPOINT_INVALID');$q=$this->pdo->prepare('SELECT * FROM control_managed_sites WHERE site_id=:site');$q->execute(['site'=>strtolower($id)]);$row=$q->fetch();if(!is_array($row))throw new HubManagedHostingOperatorException('Site was not found','SITE_NOT_FOUND');return $row; }
    private function activeRevision(string $project): ?string { $q=$this->pdo->prepare("SELECT active_revision_id FROM control_project_vaults WHERE project_id=:project AND sync_state='SYNCED'");$q->execute(['project'=>$project]);$v=$q->fetchColumn();return is_string($v)&&self::validUuid($v)?strtolower($v):null; }
    private function advertise(string $at): void { $expires=gmdate('c',strtotime($at)+180);foreach(self::CAPABILITIES as $cap)$this->pdo->prepare("INSERT INTO control_executor_capabilities(executor_id,executor_kind,capability,version,observed_at,expires_at) VALUES(:id,'VPS',:cap,'m17',:at,:expires) ON CONFLICT(executor_id,capability) DO UPDATE SET version='m17',observed_at=excluded.observed_at,expires_at=excluded.expires_at")->execute(['id'=>self::EXECUTOR,'cap'=>$cap,'at'=>$at,'expires'=>$expires]); }
    private function claim(string $at): ?array { $expires=gmdate('c',strtotime($at)+self::LEASE_SECONDS);try{$this->pdo->exec('BEGIN IMMEDIATE');$caps="'".implode("','",self::CAPABILITIES)."'";$q=$this->pdo->query("SELECT e.*,t.goal FROM control_task_executions e JOIN control_tasks t ON t.task_id=e.task_id WHERE e.state='QUEUED' AND e.executor_kind='VPS' AND e.required_capability IN ({$caps}) AND t.state IN ('QUEUED','WAITING_FOR_WORKER') ORDER BY e.created_at,e.execution_id LIMIT 1");$row=$q->fetch();if(!is_array($row)){$this->pdo->exec('COMMIT');return null;}$u=$this->pdo->prepare("UPDATE control_task_executions SET state='RUNNING',lease_owner=:owner,lease_expires_at=:expires,attempt_count=attempt_count+1,updated_at=:at WHERE execution_id=:id AND state='QUEUED'");$u->execute(['owner'=>self::EXECUTOR,'expires'=>$expires,'at'=>$at,'id'=>$row['execution_id']]);if($u->rowCount()!==1){$this->pdo->exec('ROLLBACK');return null;}$this->pdo->prepare("UPDATE control_tasks SET state='RUNNING',progress=20,updated_at=:at WHERE task_id=:task")->execute(['at'=>$at,'task'=>$row['task_id']]);$this->pdo->exec('COMMIT');return $row;}catch(Throwable $e){$this->rollbackDb();throw new HubManagedHostingOperatorException('Hosting execution could not be claimed','HOSTING_CLAIM_FAILED');} }
    private function complete(array $row,array $site,array $result,string $at): void { $summary=($result['state']??null)==='DISABLED'?'ปิดเว็บไซต์แล้ว โดยเก็บข้อมูลและ release ไว้สำหรับกู้คืน':'เว็บไซต์พร้อมใช้งาน'.(is_string($result['url']??null)?' · '.$result['url']:'');try{$this->pdo->exec('BEGIN IMMEDIATE');$this->pdo->prepare("UPDATE control_task_executions SET state='COMPLETED',lease_owner=NULL,lease_expires_at=NULL,last_error_code=NULL,updated_at=:at WHERE execution_id=:id AND lease_owner=:owner")->execute(['at'=>$at,'id'=>$row['execution_id'],'owner'=>self::EXECUTOR]);$this->pdo->prepare("UPDATE control_tasks SET state='COMPLETED',progress=100,result_summary=:summary,failure_code=NULL,updated_at=:at WHERE task_id=:task")->execute(['summary'=>$summary,'at'=>$at,'task'=>$row['task_id']]);$this->pdo->prepare("INSERT INTO control_task_events(event_id,task_id,state,progress,message,occurred_at) VALUES(:id,:task,'COMPLETED',100,:message,:at)")->execute(['id'=>self::uuid(),'task'=>$row['task_id'],'message'=>$summary,'at'=>$at]);$this->pdo->exec('COMMIT');}catch(Throwable){$this->rollbackDb();} }
    private function fail(array $row,string $code,string $at): void { $human=match($code){'PROJECT_SOURCE_NOT_READY'=>'AWH กำลังรอ Source ของโปรเจกต์ก่อนเตรียมเว็บไซต์','HOSTING_TLS_UNAVAILABLE'=>'ยังไม่พบ HTTPS identity ที่ใช้กับ VPS ได้','NODE_BUILD_REQUIRED'=>'โปรเจกต์ Node ยังไม่มี server build ที่พร้อมรัน','HOSTING_HEALTH_FAILED'=>'เว็บไซต์เริ่มทำงานแล้วแต่ health check ยังไม่ผ่าน',default=>'AWH ยังเตรียมเว็บไซต์ไม่สำเร็จ และเก็บรายละเอียดไว้ให้ Owner ตรวจ'};$waiting=in_array($code,['PROJECT_SOURCE_NOT_READY'],true);try{$this->pdo->exec('BEGIN IMMEDIATE');$this->pdo->prepare('UPDATE control_task_executions SET state=:state,lease_owner=NULL,lease_expires_at=NULL,last_error_code=:code,updated_at=:at WHERE execution_id=:id')->execute(['state'=>$waiting?'WAITING_FOR_CAPABILITY':'FAILED','code'=>$code,'at'=>$at,'id'=>$row['execution_id']]);$this->pdo->prepare('UPDATE control_tasks SET state=:state,progress=0,failure_code=:code,result_summary=:summary,updated_at=:at WHERE task_id=:task')->execute(['state'=>$waiting?'WAITING_FOR_WORKER':'FAILED','code'=>$code,'summary'=>$human,'at'=>$at,'task'=>$row['task_id']]);$checkpoint=json_decode((string)$row['checkpoint_json'],true);if(is_array($checkpoint)&&is_string($checkpoint['siteId']??null)){$this->pdo->prepare("UPDATE control_managed_sites SET state=:state,updated_at=:at WHERE site_id=:site")->execute(['state'=>$waiting?'DRAFT':'FAILED','at'=>$at,'site'=>$checkpoint['siteId']]);$this->siteEvent((string)$checkpoint['siteId'],(string)$row['task_id'],'SITE_BLOCKED',$waiting?'WAITING':'FAILED',$human,$at);}$this->pdo->exec('COMMIT');}catch(Throwable){$this->rollbackDb();} }
    private function recover(string $at): void { $q=$this->pdo->prepare("SELECT execution_id,task_id FROM control_task_executions WHERE executor_kind='VPS' AND required_capability LIKE 'hosting.%' AND state='RUNNING' AND lease_expires_at<=:at");$q->execute(['at'=>$at]);foreach($q->fetchAll() as $r){$this->pdo->prepare("UPDATE control_task_executions SET state='QUEUED',lease_owner=NULL,lease_expires_at=NULL,last_error_code='LEASE_EXPIRED',updated_at=:at WHERE execution_id=:id")->execute(['at'=>$at,'id'=>$r['execution_id']]);$this->pdo->prepare("UPDATE control_tasks SET state='WAITING_FOR_WORKER',failure_code='LEASE_EXPIRED',updated_at=:at WHERE task_id=:task")->execute(['at'=>$at,'task'=>$r['task_id']]);} }
    private function reconcileSource(string $at): void { $q=$this->pdo->query("SELECT e.execution_id,e.task_id,e.project_id,t.goal FROM control_task_executions e JOIN control_tasks t ON t.task_id=e.task_id WHERE e.executor_kind='VPS' AND e.required_capability IN ('hosting.site.provision','hosting.site.deploy') AND e.state='WAITING_FOR_CAPABILITY' AND e.last_error_code='PROJECT_SOURCE_NOT_READY' LIMIT 25");foreach($q->fetchAll() as $r){$revision=$this->activeRevision((string)$r['project_id']);if($revision===null)continue;$this->pdo->prepare("UPDATE control_task_executions SET vault_revision_id=:revision,state='QUEUED',last_error_code=NULL,updated_at=:at WHERE execution_id=:id")->execute(['revision'=>$revision,'at'=>$at,'id'=>$r['execution_id']]);$this->pdo->prepare("UPDATE control_tasks SET state='QUEUED',failure_code=NULL,updated_at=:at WHERE task_id=:task")->execute(['at'=>$at,'task'=>$r['task_id']]);} }
    private function siteEvent(string $site,?string $task,string $name,string $state,string $message,string $at): void { $this->pdo->prepare('INSERT INTO control_site_events(event_id,site_id,task_id,event_name,state,message,occurred_at) VALUES(:id,:site,:task,:name,:state,:message,:at)')->execute(['id'=>self::uuid(),'site'=>$site,'task'=>$task,'name'=>$name,'state'=>$state,'message'=>$message,'at'=>$at]); }
    private function ready(): void { HubAccountHostingMigration::assertCapabilityReady($this->pdo,dirname(__DIR__).'/migrations/016_account_hosting.sql'); }
    private function ensureDirectory(string $path,int $mode): void { if(is_link($path))throw new HubManagedHostingOperatorException('Hosting directory is unsafe','HOSTING_STORAGE_UNSAFE');if(!is_dir($path)&&!@mkdir($path,$mode,true)&&!is_dir($path))throw new HubManagedHostingOperatorException('Hosting directory is unavailable','HOSTING_STORAGE_UNAVAILABLE');@chmod($path,$mode); }
