    private function rollbackDb(): void { try{$this->pdo->exec('ROLLBACK');}catch(Throwable){} }
    private static function validHost(string $v): bool { return filter_var($v,FILTER_VALIDATE_IP)!==false||preg_match('/^[a-z0-9](?:[a-z0-9.-]{0,251}[a-z0-9])?$/i',$v)===1; }
    private static function validUuid(string $v): bool { return preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i',$v)===1; }
